  if(state.tray==='history')panel.innerHTML=`<p class="small muted">Immutable audit history · selected claim and linked evidence. Earlier findings retain their original basis.</p><ul class="record-list">${state.report.finding_history.filter(f=>f.claim_id===state.cid).reverse().map(f=>`<li><strong>Computed: ${esc(statusLabels[f.computed_status])}</strong> · Reviewed: ${esc(statusLabels[f.reviewed_status]||'Pending')}<br><time>${esc(formatTime(f.created_at))}</time>${esc(f.explanation)}${f.review_reason?`<br>Review reason: ${esc(f.review_reason)}`:''}</li>`).join('')}${relatedEvents().slice(-20).reverse().map(e=>`<li>${esc(formatTime(e.time))} · ${esc(e.author)} · ${esc(e.reason)}<details><summary>Before and after · ${esc(e.action)}</summary><pre>${esc(JSON.stringify({before:e.before,after:e.after},null,2))}</pre></details></li>`).join('')}</ul>`;
  if(state.tray==='requests')panel.innerHTML=requestsView();
