function relatedEvents(){const ids=new Set([state.cid,state.eid,...state.report.evidence_links.filter(l=>l.claim_id===state.cid).map(l=>l.evidence_id)]);return state.report.review_events.filter(e=>ids.has(e.entity_id));}
function requestsView(){return `<p class="small muted">Follow-ups · whole inspection. Closing a request does not prove support.</p>${analyst&&claim()?`<form id="create-request" class="request-form"><div class="field"><label>Claim for new request</label>${claimPicker()}</div>${field('request','What is needed?','','text','required maxlength="4000"')}${field('reason','Why is it needed?','','text','required maxlength="4000"')}<button type="submit" data-write>Create request</button></form>`:''}${state.report.follow_ups.map(q=>{const a=assetForClaim(q.claim_id),c=state.report.claims.find(c=>c.id===q.claim_id);return `<form class="request-row" data-request="${q.id}"><div><p><strong>${esc(a.tag)} · ${esc(title(c.kind))}</strong><br>${esc(q.request)}</p><small>${esc(title(q.state))}${q.resolution?` · ${esc(q.resolution)}`:''}</small></div>${analyst?`<div class="field"><label>Response / reason for ${q.state==='open'?'resolution':'reopening'}</label><textarea name="resolution" aria-label="Response for ${esc(a.tag)} ${esc(title(c.kind))}" required maxlength="4000"></textarea></div><button type="submit" data-write>${q.state==='open'?'Resolve':'Reopen'}</button>`:''}</form>`;}).join('')||'<p>No follow-ups in this inspection.</p>'}`;}
