function navigate(view){if(window.CDIV2&&!window.CDIV2.canNavigate())return;if(state.dirty&&!confirm('You have unsaved entries. Leave this task?'))return;state.dirty=false;state.view=view;history.pushState(null,'','#/'+view);render();$('#workspace').focus({preventScroll:true});focusStep();}
async function download(url,filename){const response=await api(url,{raw:true});const blob=await response.blob();const objectURL=URL.createObjectURL(blob);const a=document.createElement('a');a.href=objectURL;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(objectURL),1500);}
function selectClaim(cid,aid){if(state.dirty&&!confirm('You have unsaved entries. Switch claims?'))return;state.dirty=false;const changed=aid!==state.aid;state.cid=cid;state.aid=aid;state.reviewSaved=false;state.evidenceStep=null;state.siteObservation=null;state.sitePhoto=null;state.siteStep=1;if(changed)state.showAllFiles=false;syncEvidenceSelection();render();if(state.view==='assessment')$('.work-sheet')?.scrollIntoView({block:'start'});}
