  'scroll-right':b=>$('#'+b.dataset.target).scrollBy({left:320,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}),
  'close-details':()=>{$('#context-drawer').hidden=true;$('#details-toggle').setAttribute('aria-expanded','false');},
  'show-requests':()=>{state.tray='requests';renderTray();},
  'sample-certificate':async()=>{try{await download(root()+`/demo-certificate/${state.aid}`,`${asset().tag}-synthetic-certificate.pdf`);note('Synthetic certificate downloaded. Upload it in Evidence to test extraction and review.');}catch(e){note(e.message,true);}},
  'download-original':async()=>{if(evidence())try{await download(root()+`/evidence/${state.eid}/original`,evidence().filename);}catch(e){note(e.message,true);}},
