  complete:()=>dialog(`<h2 id="review-dialog-title">Complete this review</h2><p>Unresolved claims and open follow-ups remain visible. Completion records that the current assessment has been reviewed.</p><form id="complete-review">${reason('Summarize the review and remaining gaps')}<div class="dialog-actions">${action('close-dialog','Cancel')}<button type="submit" data-write class="primary">Complete review</button></div></form>`),
  'close-dialog':()=>$('#review-dialog').close(),
